import React from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import Home from "./pages/Home";
import Homef from "./pages/Home";
import SamplesInput from "./pages/SamplesInput";
import FeaturesInput from "./pages/FeaturesInput";
import Results from "./pages/Results";
 function App() {
  return (
     <BrowserRouter>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/samples" element={<SamplesInput />} />
        <Route path="/features" element={<FeaturesInput />} />
        <Route path="/results" element={<Results />} />
      </Routes>
    </BrowserRouter>
  )
}
export default App;
